const STAGING = 'https://qimialab.qimia.om';
const DEPARTMENTS = ['makeup', 'skin-care', 'hair-care', 'fragrance', 'body-care', 'beauty-tools'];
const COMMON = ['size','inci','directions_en','directions_ar','warnings_en','warnings_ar','benefits_en','benefits_ar','key_ingredients','key_ingredients_ar','pao','source_url'];
const EXTRA = {
  'skin-care':['skin_type','skin_concern','texture','finish','spf'],
  makeup:['finish','coverage','undertone','texture','shade_notes'],
  fragrance:['concentration','fragrance_family','top_notes','heart_notes','base_notes'],
  'hair-care':['hair_type','hair_concern','texture'],
  'body-care':['skin_type','body_concern','texture'],
  'beauty-tools':['material','dimensions','tool_care']
};
const NATIVE_KEYS = ['id','name','sku','type','parent_id','status','slug','permalink','regular_price','sale_price','price','date_on_sale_from','date_on_sale_to','manage_stock','stock_quantity','stock_status','backorders','sold_individually','categories','brands','tags','attributes','default_attributes','variations','images','description','short_description'];
const PROTECTED_META = ['_qimia_product_type','_qimia_supplement_facts','_qimia_supplement_facts_v2','_qimia_ai_box','_qimia_ai_box_v9'];
function obj(v){ return v !== null && typeof v === 'object' && !Array.isArray(v); }
function check(v, message){ if(!v) throw new Error(message); }
