function urlParts(value){
  check(typeof value==='string' && value.length<=1000, 'Source URL must be a string of at most 1000 characters.');
  // Deliberately no arbitrary URL fetches. Source URLs are research/review data only.
  const m=value.match(/^https:\/\/([a-zA-Z0-9.-]+)(?::443)?(\/[^\s#]*)?(?:#[^\s]*)?$/);
  check(m && m[1].includes('.') && !/^\d+(?:\.\d+){3}$/.test(m[1]) && !/^(localhost|.*\.local|.*\.internal)$/i.test(m[1]), 'Use a public HTTPS source without credentials or a nonstandard port.');
