  return {host:m[1].toLowerCase().replace(/^www\./,''),url:value};
}
function fieldsFor(department){
  check(DEPARTMENTS.includes(department),'Unknown Beauty department.');
  const fields = COMMON.concat(EXTRA[department].flatMap(k=>[k,k+'_ar']));
  return department==='beauty-tools'?fields.filter(k=>!['inci','key_ingredients','key_ingredients_ar','pao'].includes(k)):fields;
}
function configGuard(config){
  check(obj(config),'Configuration missing.');
  check(config.stagingOrigin===STAGING,'Only the exact Qimia staging origin is supported.');
  check(['review','apply'].includes(config.mode),'Mode must be review or apply.');
  check(Number.isSafeInteger(config.productId) && config.productId>0,'Set one existing staging parent productId in Configuration.');
  check(typeof config.expectedSku==='string' && typeof config.expectedName==='string' && (config.expectedSku.trim() || config.expectedName.trim()), 'Provide the exact expected SKU, or the exact product name when SKU is empty.');
  check(DEPARTMENTS.includes(config.department),'Choose one of the six existing Beauty departments.');
  check(config.productClass===(config.department==='beauty-tools'?'accessory':'beauty'), 'Tools must explicitly use accessory; topical cosmetics must use beauty.');
  check(Array.isArray(config.trustedSourceHosts) && config.trustedSourceHosts.every(h=>typeof h==='string' && /^[a-z0-9.-]+\.[a-z]{2,}$/i.test(h) && !/^www\./i.test(h)), 'trustedSourceHosts must contain hostnames only, without www, URLs or wildcards.');
  if(config.mode==='apply') check(obj(config.reviewedDraft),'Apply mode requires the reviewed draft from a previous review execution.');
  return config;
}
function nativeSnapshot(product){
  const out={}; for(const key of NATIVE_KEYS) if(Object.prototype.hasOwnProperty.call(product,key)) out[key]=product[key];
  // Retain all supplement-owned metadata for preservation checking; never include it in a PUT.
  out.protected_metadata=(product.meta_data||[]).filter(m=>PROTECTED_META.includes(m.key) || /(?:supplement|nutrition|serving|ai[_-]?box)/i.test(String(m.key))).map(m=>({key:m.key,value:m.value})).sort((a,b)=>a.key.localeCompare(b.key));
