  check(obj(product) && product.id===config.productId,'Woo response does not match the configured product ID.');
  check(product.parent_id===0 && ['simple','variable'].includes(product.type),'Only existing simple or variable parent products are supported. Variations and other product types are rejected.');
  check(['publish','draft','pending','private'].includes(product.status),'Unsupported product status.');
  check(config.expectedSku ? product.sku===config.expectedSku : product.name===config.expectedName, 'Expected SKU/name mismatch; review the target product.');
  check(typeof product.permalink==='string' && product.permalink.startsWith(STAGING+'/'),'Product permalink does not belong to staging.');
  check(Object.prototype.hasOwnProperty.call(product,'qimia_product_class') && obj(product.qimia_beauty_details),'Beauty REST adapter is unavailable. Do not use raw meta_data as a fallback.');
  check(product.qimia_product_class===config.productClass,'Existing resolved class differs; classify the product deliberately in WordPress first. Supplement and food products are never converted.');
  check(Array.isArray(product.categories),'Native product categories are required.');
  const known=taxonomy[config.department]||[];
  const selected=product.categories.filter(c=>known.includes(c.slug)).sort((a,b)=>Number(a.slug===config.department)-Number(b.slug===config.department))[0];
  check(selected && Number.isSafeInteger(selected.id) && selected.id>0,'Product needs a native category in the chosen Beauty department. Custom nested categories require reviewed workflow taxonomy support.');
