}
function singleTerm(value, slug){
  const arr=Array.isArray(value)?value:[value];
  check(arr.length===1 && obj(arr[0]) && arr[0].slug===slug && Number.isSafeInteger(arr[0].id),'Expected exactly one native category for '+slug+'.'); return arr[0];
}
function hierarchyGuard(ctx, assigned, departmentResponse, rootResponse){
  const department=singleTerm(departmentResponse,ctx.config.department), root=singleTerm(rootResponse,'beauty');
  check(obj(assigned) && assigned.id===ctx.selectedCategory.id && assigned.slug===ctx.selectedCategory.slug,'Assigned category lookup mismatch.');
  check(department.parent===root.id && root.parent===0,'Beauty category ancestry differs from the intended native tree.');
  check(assigned.id===department.id ? assigned.parent===root.id : assigned.parent===department.id,'Assigned category is outside the verified department ancestry.');
  return {...ctx,departmentTerm:department,rootTerm:root,baseline:snapshot(ctx.product)};
}
function parseResearch(response){
  const candidates=[];
  function visit(v,depth=0){
    if(depth>12 || v===null || v===undefined) return;
    if(typeof v==='string') { const s=v.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''); if(s.startsWith('{')){try{visit(JSON.parse(s),depth+1);}catch(e){}} return; }
    if(Array.isArray(v)){ v.forEach(x=>visit(x,depth+1));return; }
    if(obj(v)){ if(v.schema_version===1 && obj(v.facts) && obj(v.product_match)){candidates.push(v);return;} for(const k of ['message','content','output','output_text','text','response','data']) if(k in v) visit(v[k],depth+1); }
  }
  visit(response);
  check(candidates.length===1,'Research must return exactly one strict Beauty JSON object. No write was attempted.');
  return candidates[0];
}
function validateFacts(result,ctx,applying=false){
  check(obj(result) && result.schema_version===1 && obj(result.product_match),'Invalid research schema.');
  const match=result.product_match;
  check(match.exact===true && match.product_id===ctx.product.id && match.sku===ctx.product.sku,'Research must match the exact existing product ID and SKU.');
  check(typeof match.reason==='string' && match.reason.trim().length>=20,'Describe how the exact product/size/market was matched.');
  check(['single_product','parent_shared'].includes(match.variant_scope),'Unclear or variant-specific formulas cannot be assigned to the parent product.');
  if(ctx.product.type==='variable') check(match.variant_scope==='parent_shared','Variable parent data must be explicitly shared by all available variants.');
  check(Array.isArray(result.conflicts) && result.conflicts.length===0,'Conflicting source/market/formula evidence requires manual resolution.');
  check(obj(result.source) && ['manufacturer','packaging'].includes(result.source.kind),'An exact manufacturer/packaging source is required.');
  const source=urlParts(result.source.url);
  check(typeof result.source.publisher==='string' && result.source.publisher.trim(),'Name the source publisher.');
  const trusted=ctx.config.trustedSourceHosts.map(h=>h.toLowerCase());
  if(applying) check(trusted.length>0 && trusted.includes(source.host),'Review and allow the exact manufacturer/packaging host in trustedSourceHosts before applying.');
  check(obj(result.facts) && obj(result.evidence),'Facts and field-level evidence must be objects.');
  const allowed=fieldsFor(ctx.config.department), facts={};
  for(const [key,raw] of Object.entries(result.facts)){
    check(allowed.includes(key) && key!=='source_url','Unknown or department-inappropriate field: '+key);
    check(typeof raw==='string','Fact must be a string: '+key);
    const val=raw.trim();
    // Omit unknowns. Automated deletion is intentionally unsupported.
    if(!val) continue;
    const max=key==='inci'?16000:/^(directions|warnings|benefits)_/.test(key)?4000:1000;
    check([...val].length<=max,'Field exceeds contract limit: '+key);
    check(!/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(val) && !/<\/?[a-z][^>]*>/i.test(val),'Fields must be plain text: '+key);
    check(!/^(unknown|n\/?a|not (?:found|available|verified)|غير (?:معروف|متوفر|متاح))\.?$/i.test(val),'Unknown fields must be omitted: '+key);
    if(key==='pao') check(/^(?:[1-9]|[1-9][0-9])M$/.test(val),'PAO must be an exact labelled value such as 12M.');
    if(key==='spf'||key==='spf_ar') check(/^(?:[1-9][0-9]?|100)\+?$/.test(val),'SPF must be a numeric label claim.');
    if(key.startsWith('benefits_')) check(val.split(/\r\n|[\n\v\f\r\u0085\u2028\u2029]/).filter(x=>x.trim()).length<=4,'At most four benefits per language.');
    const ev=result.evidence[key];
    check(obj(ev) && typeof ev.quote==='string' && ev.quote.trim().length>=3 && ev.quote.length<=20000,'Field-level exact source quotation required: '+key);
    check(ev.url===result.source.url,'This adapter stores one provenance URL; all facts must come from the same exact source. Split mixed sources into reviewed records instead.');
    const isAr=key.endsWith('_ar');
    if(isAr && key!=='spf_ar') check(/[\u0600-\u06ff]/.test(val),'Arabic text required: '+key);
    if(isAr) check(typeof ev.translation_of==='string' && ev.translation_of===englishKey(key),'Arabic evidence must identify its exact English field: '+key);
    if(['inci','pao','spf','size'].includes(key)) check(ev.quote.includes(val),'Exact label transcription must occur verbatim in its source quote: '+key);
